/** 段を描く形にそろえる。知らない kind の段は外す。 */
const passagesOf = (passage, resolve) => {
  if (Object.hasOwn(Vocabulary.remarkKinds, passage.kind)) {
    const remark = Vocabulary.remarkKinds[passage.kind];
    return [{ kind: "remark", label: remark.label, isWarn: remark.isWarn, pieces: resolve(passage.text) }];
  }

/** タブの節と用語集。用語集は、節の用語を最初に出た順に重複なくつなぐ(1 つも無ければ null)。 */
const tabOf = (topics) => {
  const terms = [...new Map(topics.flatMap((topic) => topic.terms).map((term) => [term.id, term])).values()];
  return { topics, glossary: terms.length === 0 ? null : { terms } };
};

/**
 * 文を、印の外の文字と印に割る。空の文字は出さず、印になっていない `[[` は文字のまま残す。
 * @returns `{kind: "plain", text}` と `{kind: "term", label, id}` の並び(文の順)
 */
const piecesOf = (text) => {
  const parts = text.split(Pattern);
  const plainAt = (index) => (parts[index] === "" ? [] : [{ kind: "plain", text: parts[index] }]);
  const marks = Array.from({ length: (parts.length - 1) / 3 }, (_, index) => ({ kind: "term", label: parts[index * 3 + 1], id: parts[index * 3 + 2] }));
  return [...plainAt(0), ...marks.flatMap((mark, index) => [mark, ...plainAt(index * 3 + 3)])];
};

def plain_pieces_of(text: str) -> list[str]:
    """印で割った、印の外の切れ端。`n` 個目の切れ端は `n` 個目の印の前にある(ページの `TermMarks.piecesOf` と同じ割り方)。"""
    return TermMarkPattern.split(text)[0::3]

const tabButtons = tabs.map((tab) => {
  const button = pressable("button", { class: "primer-tab", role: "tab", id: `primer-tab-${tab}`, "aria-controls": `primer-panel-${tab}`, "data-tab": tab }, [
    el("span", { class: "primer-tab-label", text: PrimerTabTexts[tab].label }),
    el("span", { class: "primer-tab-count", text: String(parts[tab].count) }),
    el("span", { class: "primer-tab-desc", text: PrimerTabTexts[tab].description }),
  ], () => showTab(tab));
  button.addEventListener("keydown", (event) => {
    const step = Object.hasOwn(TabMoveKeys, event.key) ? TabMoveKeys[event.key] : 0;
    if (step === 0) return;
    event.preventDefault();
    const next = tabs[(tabs.indexOf(tab) + step + tabs.length) % tabs.length];
    showTab(next);
    tabButtons[tabs.indexOf(next)].focus();
  });
  return button;
});

def read(excerpt: dict, where: str) -> tuple[dict, list[str]]:
    text, problem = excerpt_text(repo, sha, excerpt)
    return (excerpt, [f"{where}: {problem}"]) if problem else ({**excerpt, "text": text}, [])

def read_route(sofar: tuple[dict, list[str]], route: str) -> tuple[dict, list[str]]:
    written, problems = read_along(sofar[0], route, read)
    return written, sofar[1] + problems

return reduce(read_route, routes_with(Shape("Excerpt")), (explain, []))

class Step(NamedTuple):
    """道筋(`a[].b`)の 1 段。`key` はキー、`is_each` は配列の各要素へ進むか、`where` は起点からそのキーまでの綴り。"""

    key: str
    is_each: bool
    where: str

    def item_where(self, index: int) -> str:
        """配列の `index` 番目の要素までの綴り。"""
        return f"{self.where}[{index}]"


def step_of(step: str, where: str) -> Step:
    """道筋の 1 段を読む(`[]` で終わる段は配列の各要素へ進む)。

    @param where 起点からその段の手前までの綴り
    """
    key = step.removesuffix("[]")
    return Step(key, step.endswith("[]"), f"{where}.{key}" if where else key)

# 技術の節(Primer)の、kind をまたいで同じキー。
PrimerFields: dict[str, Field] = {
    "id": need(Id),
    "category": need(Text),
    # 技術の名前は識別子や継ぎ目のある複合語を書くので、見出し(Heading)にしない。
    "label": need(Text),
    "gist": need(MarkedText),
    "passages": may(Many(Variant("Passage"))),
    "occurrences": need(Many(Shape("Occurrence"), least=1)),
    "seeAlso": may(Many(Id, distinct=True)),
}

# `kind` ごとに持つキー。他の kind のキーが混ざるのも、知らないキーとして落とす。Target はどの kind も、ページ
# (固定スクリプトの核の `Target`)がここと同じキーを読んで移る先にすることを `pr-explain-core-cases.sh` が確かめる。
# 同じキーは kind をまたいで同じ規則にする(`routes_under` が kind のキーを合わせて辿るため。`build-pr-explain-cases.sh` の
# 「どの Variant も、kind をまたいで同じキーは同じ規則を持つ」が確かめる)。
Variants: dict[str, dict[str, dict[str, Field]]] = {
    "Target": {
        "feature": {"id": need(Id)},
        "layer": {"layer": need(Text)},
        "file": {"path": need(Text)},
        "message": {"id": need(Id)},
        "flow": {"id": need(Id)},
    },
    "Primer": {
        "language": PrimerFields,
        "codebase": {
            **PrimerFields,
            "status": may(Word(PrimerStatuses)),
            "tests": may(Many(Id, distinct=True)),
            "flows": may(Many(Id, distinct=True)),
        },
    },
    "Passage": {
        "text": {"text": need(MarkedText)},
        "declaration": {"code": need(Text)},
        "parameters": {"parameters": need(Many(Shape("Parameter"), least=1))},
        "excerpt": {"excerpt": need(Shape("Excerpt"))},
        **{kind: {"text": need(MarkedText)} for kind in RemarkKinds},
    },
}

create: ({ topics, emptySide }) => {
  let current = topics.length === 0 ? null : 0;
  let shownCurrent = null;
  const side = el("div", { class: "side" });
  const inlineHolders = topics.map(() => el("div", { class: "side" }));
  const articles = topics.map((topic, index) => el("article", { class: "topic", ...topic.attributes }, [
    headOf(topic),
    el("details", { class: "topic-inline" }, [el("summary", { text: topic.inlineSummary }), inlineHolders[index]]),
    ...topic.body,
  ]));

  const render = () => {
    for (const [index, row] of tocRows.entries()) row.classList.toggle("is-current", index === current);
    for (const [index, holder] of inlineHolders.entries()) holder.replaceChildren(...topics[index].sideBlocksOf());
    side.replaceChildren(...(current === null ? [el("p", { class: "side-note", text: emptySide })] : [sideHeadOf(topics[current]), ...topics[current].sideBlocksOf()]));
    if (current !== shownCurrent) side.scrollTop = 0;
    shownCurrent = current;
  };

  /**
   * 節へ送る。今の節はスクロールを待たずにその節にする。
   *
   * 今の節が同じでも描き直す(`showMention` が選び直したマスの根拠を、ここで描かせるため)。
   */
  const sendTo = (index) => {
    current = index;
    render();
    articles[index].scrollIntoView({ block: "start" });
  };
  const tocRows = topics.map((topic, index) => pressable("button", { class: "row plain-button" }, tocPartsOf(topic), () => sendTo(index)));
  const tocItems = topics.flatMap((topic, index) => [...(topic.tocDivider === null ? [] : [el("div", { class: "topic-toc-divider", text: topic.tocDivider })]), tocRows[index]]);
  const toc = el("div", { class: "panel-scroll" }, tocItems.length > 0 ? tocItems : [emptyOf("節がありません。")]);

  /**
   * スクロールに合わせて今の節を決め直す。変わったときだけ描き直す。
   * @param top スクロールしている領域の上端の、表示領域の上端からの距離
   */
  const follow = (top) => {
    const next = TopicScroll.currentOf(articles.map((article) => article.getBoundingClientRect().top - top));
    if (next === current) return;
    current = next;
    render();
  };

  render();
  return { articles, toc, inlineHolders, side, follow, sendTo, render };
},

subscribe: ({ main, follow }) => {
  const isShown = () => {
    const screen = main.closest(".screen");
    return screen !== null && !screen.hidden;
  };
  // スクロールしているのが本文の欄(広い幅)かページ全体(狭い幅)かは CSS の `@media` が決めるので、イベントの出どころで見分ける。
  main.addEventListener("scroll", () => follow(main.getBoundingClientRect().top), { passive: true });
  // ページ全体のスクロールは、その画面が隠れているあいだはほかの画面のものなので見ない。
  window.addEventListener("scroll", () => {
    if (isShown()) follow(0);
  }, { passive: true });
},

return Object.freeze({
  Routes,
  Required,
  /**
   * ページが組み立てに使う形を見る。
   * @returns 型の違う道筋か、必須のキー(`Required`)が欠けた道筋(`impact.tables[].outcomes` の形)。崩れが 2 か所以上なら最も外側のもの。
   *   崩れていなければ null
   */
  problemOf: (explain) => {
    const mistyped = Routes.filter(([route, kind]) => valuesAt(explain, route.split(".")).some((value) => !ShapeKinds[kind](value))).map(([route]) => route);
    const lacking = Required.filter((required) => lacks(explain, required)).map(({ route }) => route);
    const broken = [...mistyped, ...lacking];
    if (broken.length === 0) return null;
    return broken.reduce((outer, candidate) => (depthOf(candidate) < depthOf(outer) ? candidate : outer));
  },
});

// 欠けていれば崩れとする道筋。primers・terms の下の必須のキーのうち、値が文(text)か 1 つのオブジェクト(record)のもの。
// `kinds` は、手前のオブジェクトが kind で持つキーの決まるもの(Variant)なら、そのキーを必須とする kind の並びで、それ以外の
// kind のオブジェクトには求めない。kind に依らないオブジェクト(Shape)なら null で、どれにも求める。Shapes と Variants から
// 導いたものと同じ並びで、`pr-explain-core-cases.sh` が突き合わせる。配列は欠けても `listOf` が空として読むので入れない。
const Required = Object.freeze([
  { route: "primers[].category", kinds: ["language", "codebase"] },
  { route: "primers[].label", kinds: ["language", "codebase"] },
  { route: "primers[].gist", kinds: ["language", "codebase"] },
  { route: "primers[].passages[].text", kinds: ["text", "caution", "memo", "rule", "spec", "history"] },
  { route: "primers[].passages[].code", kinds: ["declaration"] },
